create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,avatar_url text,timezone text not null default 'Asia/Jakarta',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.workspaces(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,business_type text,timezone text not null default 'Asia/Jakarta',currency char(3) not null default 'IDR',created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.workspace_members(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role text not null default 'member' check(role in('owner','admin','member')),created_at timestamptz not null default now(),unique(workspace_id,user_id));
create table public.categories(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,type text not null check(type in('revenue','expense')),created_at timestamptz not null default now(),unique(workspace_id,name,type));
create table public.transactions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,created_by uuid references public.profiles(id) on delete set null,type text not null check(type in('revenue','expense')),amount numeric(18,2) not null check(amount>0),category_id uuid references public.categories(id) on delete set null,description text,transaction_date date not null default current_date,source text not null default 'web' check(source in('web','telegram','whatsapp','api','import')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index transactions_workspace_date_idx on public.transactions(workspace_id,transaction_date desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_workspace_member(target_workspace uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members where workspace_id=target_workspace and user_id=auth.uid()); $$;
alter table public.profiles enable row level security; alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.categories enable row level security; alter table public.transactions enable row level security;
create policy "profile own read" on public.profiles for select using(id=auth.uid()); create policy "profile own update" on public.profiles for update using(id=auth.uid());
create policy "workspace insert authenticated" on public.workspaces for insert to authenticated with check(created_by=auth.uid()); create policy "workspace member read" on public.workspaces for select using(created_by=auth.uid() or public.is_workspace_member(id));
create policy "membership self insert" on public.workspace_members for insert to authenticated with check(user_id=auth.uid()); create policy "membership member read" on public.workspace_members for select using(user_id=auth.uid() or public.is_workspace_member(workspace_id));
create policy "category member all" on public.categories for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy "transaction member read" on public.transactions for select using(public.is_workspace_member(workspace_id)); create policy "transaction member insert" on public.transactions for insert with check(public.is_workspace_member(workspace_id) and created_by=auth.uid()); create policy "transaction member update" on public.transactions for update using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id)); create policy "transaction creator delete" on public.transactions for delete using(created_by=auth.uid());
